CREATE TEMP TABLE practical_test_receipt(v jsonb);
DO $test$
DECLARE m jsonb;h text;iv jsonb;tid uuid;aid uuid;token text:='practical-rollback-only';r jsonb;f jsonb;sid uuid;bad boolean;rev bigint;root_ev bigint;proof jsonb;
BEGIN
 PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();
 m:=population_top3000_202608_202609_v1.ref01_practical_material_v1();h:=encode(sha256(convert_to(m::text,'UTF8')),'hex');
 IF (m->>'selected_company_count')::int<>3000 OR (SELECT count(DISTINCT v->>'company_id') FROM jsonb_array_elements(m->'companies')v)<>3000 THEN RAISE EXCEPTION 'COUNT_OR_UNIQUENESS';END IF;
 IF population_top3000_202608_202609_v1.ref01_practical_material_v1() IS DISTINCT FROM m THEN RAISE EXCEPTION 'NONDETERMINISTIC';END IF;
 iv:=jsonb_build_object('policy_sha256',m->>'policy_sha256','cohort_sha256',h,'source_sha256',m->>'source_sha256');
 tid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','DERIVE','practical-cohort-v1:'||h,jsonb_build_object('kind','PRACTICAL_COHORT_CANDIDATE_V1','snapshot_sha256',h),iv);
 FOR iteration IN 1..2 LOOP
 aid:=gen_random_uuid();
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=aid,lease_until=clock_timestamp()+interval '10 minutes',owner_fence=3,stop_generation=1 WHERE task_id=tid;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256)
 SELECT aid,tid,1,encode(sha256(convert_to(token,'UTF8')),'hex'),3,1,function_sha256 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='REF01' AND stage='DERIVE';
 IF iteration=1 THEN
 BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{policy_sha256}','"bad"'::jsonb) WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_worker_v1(aid,token);RAISE EXCEPTION 'BAD_POLICY_ACCEPTED'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='BAD_POLICY_ACCEPTED' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{source_sha256}','"bad"'::jsonb) WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ref01_practical_worker_v1(aid,token);RAISE EXCEPTION 'BAD_SOURCE_ACCEPTED'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='BAD_SOURCE_ACCEPTED' THEN RAISE;END IF;END;
 END IF;
 r:=population_top3000_202608_202609_v1.ref01_adjudication_route_v3(aid,token,'DERIVE');
 IF (population_top3000_202608_202609_v1.ref01_practical_worker_v1(aid,token)#>>'{commit_receipt,new_committed_units}')::int<>0 THEN RAISE EXCEPTION 'REPLAY_DUPLICATED_OUTPUT';END IF;
 f:=population_top3000_202608_202609_v1.pipeline_finish_v1(aid,token,r);
 IF r->>'state'<>'COMPLETE' OR (r#>>'{commit_receipt,new_committed_units}')::int<1 THEN RAISE EXCEPTION 'NO_USEFUL_COMMIT';END IF;
 IF iteration=1 THEN tid:=(r#>>'{commit_receipt,population_successor}')::uuid; END IF;
 END LOOP;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_population_v1 WHERE snapshot_sha256=h)<>(SELECT count(*) FROM population_top3000_202608_202609_v1.catalog_family_contract) THEN RAISE EXCEPTION 'DOWNSTREAM_MISSING';END IF;
 BEGIN
 UPDATE population_top3000_202608_202609_v1.ref01_adjudication_case_v3 c SET content=jsonb_set(content,'{unresolved_codes}','["SECURITY_CLASSIFICATION_REQUIRED"]'::jsonb),record_sha256=encode(sha256(convert_to((jsonb_set(content,'{unresolved_codes}','["SECURITY_CLASSIFICATION_REQUIRED"]'::jsonb))::text,'UTF8')),'hex')
 FROM population_top3000_202608_202609_v1.ref01_adjudication_head_v3 x WHERE c.run_key=x.run_key AND c.case_key=x.case_key AND c.revision_key=x.revision_key AND c.case_key=m#>>'{companies,0,company_id}';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(population_top3000_202608_202609_v1.ref01_practical_material_v1()->'companies')v WHERE v->>'company_id'=m#>>'{companies,0,company_id}') THEN RAISE EXCEPTION 'IDENTITY_HOLD_ACCEPTED';END IF;
 RAISE EXCEPTION 'EXPECTED_REVERT';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'EXPECTED_REVERT' THEN RAISE;END IF;END;
 BEGIN
 UPDATE population_top3000_202608_202609_v1.ref01_adjudication_case_v3 c SET content=jsonb_set(content,'{unresolved_codes}','["ADR_GLOBAL_CAP_AND_RATIO_RECONCILIATION"]'::jsonb),record_sha256=encode(sha256(convert_to((jsonb_set(content,'{unresolved_codes}','["ADR_GLOBAL_CAP_AND_RATIO_RECONCILIATION"]'::jsonb))::text,'UTF8')),'hex')
 FROM population_top3000_202608_202609_v1.ref01_adjudication_head_v3 x WHERE c.run_key=x.run_key AND c.case_key=x.case_key AND c.revision_key=x.revision_key AND c.case_key=m#>>'{companies,0,company_id}';
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(population_top3000_202608_202609_v1.ref01_practical_material_v1()->'companies')v WHERE v->>'company_id'=m#>>'{companies,0,company_id}') THEN RAISE EXCEPTION 'CAP_ONLY_HOLD_REJECTED';END IF;
 RAISE EXCEPTION 'EXPECTED_REVERT';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'EXPECTED_REVERT' THEN RAISE;END IF;END;
 -- Changes to later evidence cannot replace a frozen candidate in population consumption.
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_snapshot_v1 WHERE membership_accepted) THEN RAISE EXCEPTION 'FALSE_ACCEPTANCE';END IF;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();RAISE EXCEPTION 'STOP_ACCEPTED'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='STOP_ACCEPTED' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_fence=4 WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();RAISE EXCEPTION 'OWNER_ACCEPTED'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='OWNER_ACCEPTED' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET admitted_until=clock_timestamp()-interval '1 second' WHERE singleton;PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();RAISE EXCEPTION 'EXPIRY_ACCEPTED'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='EXPIRY_ACCEPTED' THEN RAISE;END IF;END;

 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('PRACTICAL_COHORT_INDEPENDENT_SOURCE_REVIEW_V1','{"reviewer": "/root/cohort_reviewer", "producer": "/root/cohort_producer", "assignment_event_id": 23382, "review_kind": "PRACTICAL_HISTORICAL_SNAPSHOT_SOURCE_REVIEW", "result": "PASS_CANDIDATE_SOURCE_CHECKS_ONLY", "checked_at": "2026-10-24T11:52:00.639716Z", "selected_company_count": 3000, "selected_instrument_point_count": 3000, "eligible_company_count": 4331, "selected_adr_count": 247, "retained_original_bodies_independently_rehashed": 3014, "body_hash_mismatches": 0, "census_record_hash_mismatches": 0, "overview_record_hash_mismatches": 0, "identity_listing_field_mismatches": 0, "selection_proxy_field_mismatches": 0, "overview_request_dates": "All 3000 are 2026-08-03", "census_request_dates": "14 pages: first direct request date 2026-08-03; 13 exact chained cursors independently decoded with date=2026-08-03", "cursor_chain_mismatches": 0, "cursor_date_mismatches": 0, "direct_date_check_correction": "2722 census rows had cursor-only request parameters, not a conflicting date. Exact chain and decoded date checks resolved this initial missing-direct-date diagnostic.", "snapshot_sha256": "2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec", "company_manifest_sha256": "4134b415e2c26fcde9fced749c0d54ef51376e23f0d2f8c6ce9ef562f9fab99f", "instrument_manifest_sha256": "d21914d0a729a34c6c5650fd84dd12f8e6f46f2cee0dac415b105bb3474b3e0e", "source_snapshot_sha256": "c0847f36b52cb7e029424f1434bedc7e48ac8055d9a1590bc08ed87e60c77825", "policy_sha256": "3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb", "membership_accepted": false, "original_historical_receipt_proven": false, "full_period_instrument_completeness": false, "financial_facts_verified": false, "unverified_rank_date_share_flags_preserved": 3000, "new_provider_calls": 0, "limitations": "Review validates retained historical request reconstruction and deterministic candidate selection. It does not certify exact global top-3000 rank, financial values, complete August-September listing intervals, family acceptance or serving publication. Root membership acceptance route remains separate executable work."}'::jsonb) RETURNING event_id INTO rev;
 BEGIN PERFORM population_top3000_202608_202609_v1.ref01_practical_accept_v1(h,rev,0);RAISE EXCEPTION 'ROOTLESS_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM='ROOTLESS_ACCEPTED' THEN RAISE;END IF;END;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ROOT_PRACTICAL_COHORT_MEMBERSHIP_ACCEPTANCE_V1',jsonb_build_object('owner_id','top3000-completion-20261024-root-5db48b32d103','issued_by','top3000-completion-20261024-root-5db48b32d103','owner_fence',3,'stop_generation',1,'authority_event_id',9528,'cohort_policy_authority_event_id',23086,'scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','snapshot_sha256',h,'policy_sha256',m->>'policy_sha256','independent_review_event_id',rev,'membership_only',true,'financial_facts_accepted',false,'full_period_instruments_accepted',false,'family_acceptance',false,'serving_promoted',false)) RETURNING event_id INTO root_ev;
 BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_event SET details=jsonb_set(details,'{issued_by}','"wrong-owner"'::jsonb) WHERE event_id=root_ev;PERFORM population_top3000_202608_202609_v1.ref01_practical_accept_v1(h,rev,root_ev);RAISE EXCEPTION 'WRONG_ROOT_ACCEPTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM='WRONG_ROOT_ACCEPTED' THEN RAISE;END IF;END;
 proof:=population_top3000_202608_202609_v1.ref01_practical_accept_v1(h,rev,root_ev);
 IF population_top3000_202608_202609_v1.ref01_practical_accept_v1(h,rev,root_ev) IS DISTINCT FROM proof THEN RAISE EXCEPTION 'ACCEPTANCE_REPLAY_CHANGED';END IF;
 tid:=(proof->>'successor_task_id')::uuid;aid:=gen_random_uuid();
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=aid,lease_until=clock_timestamp()+interval '10 minutes',owner_fence=3,stop_generation=1 WHERE task_id=tid;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) SELECT aid,tid,1,encode(sha256(convert_to(token,'UTF8')),'hex'),3,1,function_sha256 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='REF01' AND stage='DERIVE';
 r:=population_top3000_202608_202609_v1.ref01_adjudication_route_v3(aid,token,'DERIVE');
 f:=population_top3000_202608_202609_v1.pipeline_finish_v1(aid,token,r);
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_population_v1 WHERE snapshot_sha256=h AND acceptance_sha256<>'')<>24 THEN RAISE EXCEPTION 'ACCEPTED_POPULATION_CHAIN_FAILED';END IF;
 INSERT INTO practical_test_receipt VALUES(jsonb_build_object('result','PASS','selected_company_count',3000,'eligible_company_count',m->>'eligible_company_count','snapshot_sha256',h,'source_sha256',m->>'source_sha256','company_sha256',m->>'company_sha256','instrument_sha256',m->>'instrument_sha256','instrument_count',jsonb_array_length(m->'instruments'),'source_and_candidate_deterministic',true,'three_real_commit_chains',true,'rootless_acceptance_rejected',true,'root_acceptance_synthetic_proof_rolled_back',true,'family_populations',(SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_population_v1 WHERE snapshot_sha256=h),'user_stop_owner_expiry_rejected',true,'root_acceptance_preserved',true));
END $test$;
SELECT v FROM practical_test_receipt;
ROLLBACK;
